INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Python Basics', 'Easy', 'What are the core characteristics of Python that make it widely popular for data science and analysis?', 'Python is a high-level interpreted programming language known for its clear syntax, readability, and dynamic typing, which allow developers to write concise code with fewer lines compared to other languages. It features an extensive standard library and a vast ecosystem of third-party packages specifically designed for numerical computation, data manipulation, machine learning, and visualization. Its object-oriented nature and platform independence make it extremely versatile for both rapid prototyping and large-scale data pipelines. Furthermore, Python boasts a massive active developer community that continuously contributes documentation, tutorials, and open-source libraries, significantly lowering the learning curve for beginners and professionals alike.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Python Data Types', 'Easy', 'Explain the difference between mutable and immutable data types in Python with common examples.', 'In Python, data types are categorized based on whether their values can be modified after creation. Mutable objects allow their internal state or contents to be changed in place without altering their memory address, and common examples include lists, dictionaries, and sets. Conversely, immutable objects cannot be modified once they are created; any attempt to change their value results in the creation of a brand new object in memory, with common examples being integers, floats, strings, tuples, and booleans. Understanding this distinction is crucial for memory management, debugging reference errors, and optimizing performance when passing variables through functions or storing them in collections during data analysis tasks.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Conditional Statements', 'Easy', 'How do conditional statements control program execution flow in Python data processing scripts?', 'Conditional statements use boolean expressions that evaluate to either true or false to determine which block of code should be executed next in a program. By using structures like if, elif, and else, developers can introduce decision-making logic to handle different data scenarios, such as filtering missing values, checking threshold boundaries, or categorizing numerical variables into distinct bins. When a condition evaluates to true, the corresponding indented block runs, while alternative blocks are skipped. This control flow mechanism enables data scripts to dynamically adapt to varying data inputs, ensuring robust data cleaning pipelines and automated decision rules operate correctly across diverse datasets.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Mean', 'Easy', 'What is the arithmetic mean, and why is it a widely used measure of central tendency in statistics?', 'The arithmetic mean, commonly known as the average, is calculated by summing all numerical values in a dataset and dividing that total by the exact count of observations. It serves as a fundamental measure of central tendency because it incorporates every single data point, providing a balanced mathematical representation of the entire dataset center. This property makes it intuitive to calculate and essential for parametric statistical tests. However, the mean is sensitive to extreme outliers and skewed distributions, where extremely high or low values can disproportionately pull the average, necessitating complementary metrics like the median for comprehensive exploratory data analysis.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Median', 'Medium', 'How is the median determined in a dataset, and when is it preferred over the mean?', 'The median is the middle value in a dataset when all observations are arranged in ascending or descending order. If the dataset contains an odd number of observations, the median is the single middle value, whereas for an even number, it is calculated as the arithmetic average of the two middle numbers. The median is strongly preferred over the mean when dealing with skewed distributions or datasets containing extreme outliers, because it is a robust statistic that remains unaffected by extremely large or small values. This makes the median an exceptionally reliable indicator of typical center values in real-world data like income distributions.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Variance', 'Medium', 'What does variance measure in a dataset, and how do sample variance and population variance differ?', 'Variance is a fundamental measure of statistical dispersion that quantifies how far individual data points deviate from the dataset mean on average. It is calculated by taking the average of the squared differences between each data point and the mean. Population variance measures the dispersion for an entire finite group of observations and divides the sum of squared deviations by the total count. In contrast, sample variance estimates the dispersion using a subset drawn from a larger population and divides by one less than the sample size, which applies Bessel correction to prevent underestimating the true population parameter.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Standard Deviation', 'Medium', 'Why is standard deviation often preferred over variance when interpreting data dispersion?', 'Standard deviation is the square root of the variance, and it is universally preferred in data analysis because it is expressed in the exact same original units of measurement as the underlying data. While variance squares the deviations, resulting in squared units that are difficult to interpret intuitively, standard deviation brings the scale back to normal. This allows data scientists to easily understand data spread, establish confidence intervals, and apply empirical rules such as determining what proportion of observations fall within specific distances from the mean in normally distributed datasets, making it an invaluable descriptive statistic.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Probability Basics', 'Medium', 'Explain the fundamental concepts of sample space and probability of independent events.', 'In probability theory, the sample space represents the complete set of all possible outcomes that can occur in a random experiment or trial. An event is any subset of outcomes drawn from this sample space. Two events are considered independent when the occurrence or outcome of the first event does not affect, influence, or change the probability of the second event occurring. To calculate the combined probability of multiple independent events happening together, you multiply their individual probabilities. This fundamental principle forms the bedrock for modeling complex probabilistic systems, risk analysis, and building reliable machine learning classification algorithms across various domains.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Object-Oriented Programming in Python', 'Hard', 'How do classes and inheritance support code reusability and modular design in Python data projects?', 'Object-oriented programming in Python uses classes as blueprints to bundle data attributes and associated methods into cohesive user-defined objects. Inheritance allows new child classes to adopt properties and methods from existing parent classes, establishing a hierarchical relationship that promotes code reuse and eliminates redundancy across complex codebases. In data science applications, developers often create custom base classes for data transformers or model evaluators, then inherit specialized subclasses for specific algorithms. This modular architecture makes large analytical pipelines significantly easier to maintain, test, extend, and collaborate on across multi-developer engineering teams.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Data Distribution', 'Hard', 'What is a data distribution, and why is identifying whether a distribution is normal important in data science?', 'A data distribution describes how the values of a variable are spread across all possible outcomes, often visualized using histograms or density plots to reveal underlying patterns, frequencies, and symmetry. Identifying whether a dataset follows a normal distribution is crucial because many parametric statistical tests, regression models, and machine learning algorithms assume normality for valid hypothesis testing, accurate coefficient estimation, and reliable predictions. When data is heavily skewed, data scientists must apply mathematical transformations or utilize non-parametric methods to avoid biased conclusions, making distribution analysis a critical exploratory step before modeling.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES
(3, 'Python Lists', 'Easy', 'What is a Python list and what are its key characteristics when storing collections of data?', 'A Python list is a versatile built-in data structure used to store an ordered collection of items. Lists are mutable, meaning you can easily add, remove, or modify their elements after creation without needing to create a new list. They can also hold heterogeneous data types, allowing a single list to contain integers, strings, and even other lists simultaneously. Elements within a list are indexed starting from zero, enabling efficient retrieval and traversal through loops or slicing operations. Their flexibility and dynamic resizing make lists essential for managing sequential data in data science workflows before converting them into specialized arrays.'),
(3, 'Python Dictionaries', 'Easy', 'How do Python dictionaries store data, and why are they useful in data processing?', 'Python dictionaries store data in key-value pairs rather than indexed numerical positions. Each key must be unique and immutable, such as a string or number, while values can be of any data type and can be duplicated. Dictionaries use hash tables under the hood, which allows for extremely fast data lookup, insertion, and deletion operations regardless of the dictionary size. In data processing and exploratory analysis, dictionaries are extremely useful for mapping relationships, aggregating frequency counts, and structuring configuration settings or JSON payloads fetched from web APIs before loading them into tabular data structures.'),
(3, 'Exception Handling', 'Easy', 'What is the purpose of exception handling in Python, and how do try and except blocks work?', 'Exception handling in Python is a mechanism used to gracefully manage runtime errors without crashing the entire program. When a block of code encounters an unexpected error, such as dividing by zero or attempting to open a non-existent file, it raises an exception. By wrapping such risky code inside a try block, the program can intercept the error and execute alternative instructions defined within an except block. This prevents sudden script termination, allows developers to log helpful diagnostic messages, and ensures that resources like file handles or database connections are properly cleaned up during execution.'),
(3, 'List Comprehensions', 'Easy', 'What is a list comprehension in Python and what advantages does it offer over traditional loops?', 'A list comprehension is a concise and readable syntactic construct in Python used to create new lists based on existing iterables. Instead of writing a traditional multi-line for loop with an appended condition, a list comprehension allows you to combine the loop and conditional filtering into a single, compact line of code. Beyond improving code readability and compactness, list comprehensions are generally optimized at the interpreter level to execute faster than standard loops that use the append method. They are widely utilized by data scientists for quick data transformation, filtering lists, and preprocessing iterable data collections efficiently.'),
(3, 'Pandas DataFrames', 'Medium', 'What is a Pandas DataFrame, and why is it considered a foundational tool for data analysis in Python?', 'A Pandas DataFrame is a two-dimensional, size-mutable, and potentially heterogeneous tabular data structure equipped with labeled axes for both rows and columns. It functions essentially like an in-memory spreadsheet or SQL table, making it exceptionally powerful for structured data manipulation. Data scientists rely heavily on DataFrames because they simplify complex operations such as filtering, grouping, merging, and reshaping datasets with concise syntax. Furthermore, DataFrames seamlessly integrate with missing data handling functions and statistical calculation methods, bridging the gap between raw unstructured data sources and advanced machine learning modeling pipelines.'),
(3, 'Missing Values', 'Medium', 'Why do datasets often contain missing values, and what are the standard strategies for handling them?', 'Datasets frequently contain missing values due to various real-world issues such as sensor malfunctions, survey non-responses, data corruption during transfer, or system integration failures. Ignoring missing data can severely bias statistical models and cause runtime errors in machine learning algorithms. Standard mitigation strategies include deletion, where rows or columns with missing entries are removed if the data loss is minimal, and imputation, where missing entries are filled using statistical estimates like the mean, median, mode, or advanced predictive modeling. The choice of strategy depends heavily on the dataset size and the underlying pattern of missingness.'),
(3, 'Sampling Techniques', 'Medium', 'What is the difference between probability and non-probability sampling techniques in data collection?', 'Probability sampling involves random selection methods where every member of a population has a known, non-zero probability of being chosen, which minimizes selection bias and allows researchers to calculate sampling error reliably. Common examples include simple random sampling, stratified sampling, and systematic sampling. In contrast, non-probability sampling relies on subjective methods where population members do not have equal chances of selection, such as convenience sampling or quota sampling. While non-probability sampling is often quicker and cheaper to execute, it lacks statistical guarantees, making it harder to generalize findings accurately to the broader target population.'),
(3, 'Exploratory Data Analysis (EDA)', 'Medium', 'What is Exploratory Data Analysis (EDA), and what role does it play in the data science lifecycle?', 'Exploratory Data Analysis is an investigative process where data scientists analyze datasets using statistical graphics and summary statistics to uncover underlying patterns, spot anomalies, test hypotheses, and check assumptions. It serves as the crucial first step after data cleaning, helping professionals understand the structural distribution and relationships within the data before building formal models. Through EDA, analysts can identify skewness, detect outliers, and select appropriate feature engineering techniques. By visualizing data distributions and correlations early, teams avoid costly modeling mistakes and ensure their machine learning algorithms are trained on well-understood data.'),
(3, 'Correlation', 'Hard', 'What does correlation measure in statistics, and why is high correlation not sufficient to prove causation?', 'Correlation measures the strength and direction of the linear or monotonic relationship between two quantitative variables, typically expressed through coefficients ranging from negative one to positive one. While correlation indicates that two variables move together in a predictable pattern, it does not prove that one variable causes changes in the other. Causation requires establishing temporal precedence, eliminating confounding variables, and confirming underlying mechanisms through controlled experiments. Assuming causation from correlation is a dangerous logical fallacy because the observed relationship might be driven entirely by an unobserved third confounding factor or happen purely by random coincidence.'),
(3, 'Covariance', 'Hard', 'How does covariance measure the joint variability of two random variables, and what are its primary limitations?', 'Covariance is a statistical metric that evaluates how two random variables change together, indicating whether they tend to move in the same direction or opposite directions. A positive covariance signifies that when one variable increases, the other tends to increase as well, whereas a negative covariance indicates they move inversely. However, the primary limitation of covariance is that its numerical value is unscaled and depends entirely on the units of measurement of the variables, making it impossible to compare covariance values across different datasets with varying scales. This limitation is overcome by correlation coefficients, which standardize the metric.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES
(3, 'Machine Learning', 'Easy', 'What is machine learning and how does it differ from traditional programming?', 'Machine learning is a branch of artificial intelligence that allows computer systems to learn and improve from experience without being explicitly programmed with hardcoded rules. In traditional programming, developers write specific instructions and rules that a computer follows to process input data and produce output. In contrast, machine learning algorithms use historical data to automatically discover underlying patterns, relationships, and statistical rules. By analyzing large amounts of training examples, the system builds an internal model that can make accurate predictions or decisions when presented with new, unseen data, enabling software to adapt and perform complex tasks autonomously.'),
(3, 'Supervised Learning', 'Easy', 'What is supervised learning in machine learning?', 'Supervised learning is a type of machine learning where an algorithm is trained using labeled input data that includes both the input features and the correct corresponding output answers. During the training phase, the model learns the mathematical relationship between the input variables and the known target values by minimizing errors in its predictions. Once trained, the model can apply this learned mapping to predict outcomes for new, unseen data points where the target label is unknown. Common real world applications of this approach include spam email detection, house price prediction, and customer churn forecasting.'),
(3, 'Unsupervised Learning', 'Easy', 'What is unsupervised learning and when is it used?', 'Unsupervised learning is a machine learning technique where algorithms are provided with unlabeled input data containing no predefined target answers or correct outputs. The primary goal of this approach is to explore the dataset independently to discover hidden structures, natural groupings, or underlying patterns without human guidance. It is commonly used when data scientists want to segment customer bases into distinct purchasing behaviors, compress high dimensional datasets while preserving essential information, or detect unusual anomalies in network traffic. Because the algorithm receives no feedback on correct answers, evaluation relies heavily on internal cluster cohesion and separation metrics.'),
(3, 'Features and Labels', 'Easy', 'What is the difference between features and labels in machine learning datasets?', 'In machine learning datasets, features represent the individual measurable input variables, characteristics, or independent attributes that describe each observation or data point. For example, in a housing dataset, features might include square footage, number of bedrooms, and geographic location. Labels, on the other hand, represent the target variable, dependent output, or correct answer that the predictive model is trying to learn to estimate. Continuing with the housing example, the label would be the final selling price of the house. Algorithms use the input features during training to map out patterns that accurately predict or classify the corresponding labels for new data.'),
(3, 'Overfitting', 'Medium', 'What is overfitting in machine learning and how can it be prevented?', 'Overfitting occurs when a machine learning model learns the training data too well, capturing random noise and minor fluctuations instead of the general underlying trend. As a result, the model achieves exceptionally high accuracy on the training set but performs poorly when exposed to new, unseen test data because it has failed to generalize. This issue typically happens when models are overly complex, possess too many parameters, or are trained for too many epochs. To prevent overfitting, data practitioners can use regularization techniques, acquire more diverse training data, apply dropout layers in neural networks, simplify the model architecture, or employ early stopping during the training process.'),
(3, 'Underfitting', 'Medium', 'What is underfitting and what causes it in machine learning models?', 'Underfitting occurs when a machine learning model is too simple or insufficiently trained to capture the underlying patterns and relationships within the dataset. Because of this limitation, an underfitted model performs poorly on both the training data and new, unseen test data, exhibiting high bias and low predictive capability. This issue is typically caused by using a model architecture that is overly simplistic for the complexity of the data, such as trying to fit a linear regression line to a heavily non-linear dataset. To fix underfitting, data scientists can increase model complexity, add more relevant input features, remove excessive regularization constraints, or extend the training duration.'),
(3, 'Train-Test Split', 'Medium', 'What is the purpose of a train-test split in machine learning workflows?', 'A train-test split is a fundamental validation technique where an available dataset is divided into two separate subsets, typically allocating the majority for training and the remaining portion for testing. The training set is used by the algorithm to learn patterns, adjust internal weights, and build the predictive model. The test set is kept completely isolated and hidden during training, serving as an unbiased benchmark to evaluate how well the trained model generalizes to new, unseen data. By testing on data the model has never encountered before, data scientists can accurately detect issues like overfitting and ensure realistic performance estimates before deploying models into production environments.'),
(3, 'Cross Validation', 'Medium', 'What is k-fold cross-validation and why is it used in machine learning?', 'K-fold cross-validation is a robust model evaluation technique where the original dataset is partitioned into k equal sized subsets or folds. The training and evaluation process is then repeated k times, with each fold taking a turn as the validation set while the remaining k minus one folds combine to form the training set. Finally, the performance metrics obtained across all k iterations are averaged to produce a single reliable performance score. This method ensures that every data point gets used for both training and testing, maximizing data utilization and providing a much more stable and accurate estimate of model generalization than a single train-test split.'),
(3, 'Bias and Variance', 'Hard', 'Explain the tradeoff between bias and variance in machine learning models.', 'The bias-variance tradeoff is a fundamental challenge in supervised learning that involves balancing two competing sources of prediction error to achieve optimal model performance. Bias refers to the error introduced by using overly simplistic assumptions, causing models to miss underlying patterns and leading to high underfitting. Variance measures how much a model''s predictions fluctuate when trained on different subsets of data, where overly complex models capture random noise resulting in severe overfitting. As model complexity increases, bias typically decreases while variance increases. Finding the ideal sweet spot minimizes total error and ensures the model generalizes well to new, unseen real-world data.'),
(3, 'Hyperparameters', 'Hard', 'What are hyperparameters and how do they differ from model parameters?', 'Hyperparameters are external configuration settings and structural choices defined by data scientists prior to initiating the training process of a machine learning algorithm. Examples include learning rate, depth of a decision tree, and the number of hidden layers in a neural network. Unlike model parameters, which are internal variables estimated automatically by the algorithm from the training data during learning, hyperparameters cannot be directly learned from data and must be tuned manually or through automated search strategies. Properly optimizing these settings is crucial because they directly govern the training dynamics, model complexity, and overall predictive accuracy on unseen testing datasets.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES
(3, 'Natural Language Processing', 'Easy', 'What is Natural Language Processing and why is it important in data science?', 'Natural Language Processing is a subfield of artificial intelligence and computer science focused on enabling computers to understand, interpret, and generate human language. It bridges the gap between human communication and machine understanding, allowing systems to analyze massive amounts of textual data. In data science, this technology is vital because a large portion of real-world information is unstructured text, such as customer reviews, support tickets, and social media posts. By applying processing techniques, data scientists can extract valuable insights, automate customer service workflows, perform sentiment analysis, and build intelligent conversational agents that enhance business decision-making.'),
(3, 'Text Preprocessing', 'Easy', 'What is text preprocessing and why must raw text be cleaned before analysis?', 'Text preprocessing is the essential first step in natural language processing where raw text data is cleaned, normalized, and transformed into a format that machine learning models can understand. Raw text often contains noise such as punctuation marks, special characters, HTML tags, and inconsistent capitalization that can confuse algorithms and degrade performance. Cleaning text ensures that identical words with different letter cases are treated uniformly while removing irrelevant elements that do not contribute to the underlying meaning. This structured preparation significantly improves the accuracy of subsequent feature extraction and text classification models.'),
(3, 'Tokenization', 'Easy', 'How does tokenization work in natural language processing?', 'Tokenization is the foundational process of breaking down a continuous stream of text, such as a sentence or a paragraph, into smaller, manageable units called tokens. These tokens are typically individual words, but they can also be characters or subwords depending on the specific application requirements. By segmenting text into discrete pieces, tokenization allows algorithms to analyze word frequencies, examine contextual relationships, and convert textual data into numerical vectors. This step acts as a bridge between raw string data and structured numerical arrays required by machine learning algorithms for further natural language processing tasks.'),
(3, 'Stop Words', 'Easy', 'What are stop words in text analysis and why are they typically removed?', 'Stop words are extremely common words in any language, such as articles, pronouns, and prepositions like the, is, at, and which, that carry very little substantive meaning on their own. In text analysis and information retrieval, these words appear with high frequency across almost all documents without providing useful context about the specific topic. Removing stop words during preprocessing is a standard practice because it drastically reduces the overall dataset size, decreases computational complexity, and prevents frequent trivial words from overshadowing important domain-specific keywords during feature extraction and similarity calculations.'),
(3, 'Stemming', 'Medium', 'What is stemming in text processing and what are its limitations?', 'Stemming is a text normalization technique that reduces inflected or derived words down to their root form by crudely chopping off prefixes or suffixes based on a set of heuristic rules. For example, words like running, runs, and ran might all be reduced to the common stem run. While stemming is computationally fast and reduces vocabulary dimensionality, its main limitation is that it often produces non-dictionary root words or stems that lack proper semantic meaning, such as reducing organizational to organ. This lack of linguistic accuracy can occasionally degrade the quality of downstream text classification and sentiment analysis tasks.'),
(3, 'Lemmatization', 'Medium', 'How does lemmatization differ from stemming in natural language processing?', 'Lemmatization is an advanced text normalization technique that reduces words to their proper dictionary base form known as a lemma, taking into account the surrounding context and grammatical part of speech. Unlike crude stemming, which simply chops off word endings, lemmatization uses vocabulary and morphological analysis to ensure that the resulting root word is always a valid and meaningful word. For instance, the past tense verb better might correctly remain unchanged or map properly, while words like is and are both correctly convert to be. This linguistic precision preserves accurate semantic meaning for advanced machine learning models.'),
(3, 'Bag of Words', 'Medium', 'What is the Bag of Words model and what are its main drawbacks?', 'The Bag of Words model is a simplifying representation used in natural language processing where a text document is treated as an unordered collection of its words, completely disregarding grammar, syntax, and word order while focusing solely on word counts or frequencies. While this method successfully converts unstructured text into numerical feature vectors that machine learning algorithms can process, it has significant drawbacks. It fails to capture semantic meaning, context, or word relationships, meaning sentences with opposite meanings can have identical representations. Additionally, large vocabularies result in high-dimensional and extremely sparse matrices that require significant computational memory.'),
(3, 'TF-IDF', 'Medium', 'How does TF-IDF evaluate the importance of words in a document collection?', 'TF-IDF, which stands for Term Frequency-Inverse Document Frequency, is a numerical statistic designed to reflect how important a specific word is to a document within a larger collection or corpus. Term frequency measures how often a word appears in a particular document, while inverse document frequency decreases the weight of words that occur very frequently across many documents, such as common stop words. By multiplying these two metrics, TF-IDF assigns higher scores to terms that are frequent in a specific document but rare across the entire corpus, effectively highlighting distinctive keywords while filtering out noise.'),
(3, 'Cosine Similarity', 'Hard', 'What is cosine similarity and how is it used in text document comparison?', 'Cosine similarity is a mathematical metric used to measure how similar two vectors are, regardless of their magnitude, by calculating the cosine of the angle between them in a multidimensional space. In text mining and natural language processing, documents are typically converted into numerical vectors using models like TF-IDF or word embeddings. When comparing two document vectors, a cosine similarity score of one indicates identical orientation and high textual similarity, while a score of zero means the documents share no overlapping terms. This metric is widely employed in search engines, recommendation systems, and plagiarism detection tools.'),
(3, 'N-grams', 'Hard', 'What are n-grams in text analysis and how do they improve context capture?', 'N-grams are contiguous sequences of n items, such as words or characters, extracted from a given sample of text to capture local contextual patterns that standard single-word models miss. For instance, a bigram extracts pairs of adjacent words, allowing the model to distinguish between phrases like not good and good by preserving word order and immediate context. By incorporating bi-grams or trigrams into text vectorization, data scientists can capture negation, compound phrases, and subtle linguistic nuances that improve the performance of sentiment analysis, language modeling, and text classification systems despite increasing vocabulary dimensionality.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Accuracy', 'Easy', 'What is accuracy in the context of classification model evaluation, and why can it be misleading when dealing with imbalanced datasets?', 'Accuracy is a fundamental evaluation metric used in machine learning classification models to measure the proportion of correctly predicted data instances out of the total number of evaluated samples. It is calculated by dividing the sum of true positives and true negatives by the total sample count. While accuracy offers a straightforward and intuitive percentage representing overall model correctness, it can become highly misleading when evaluating imbalanced datasets where one class vastly outnumbers another. For instance, if ninety-nine percent of patients do not have a rare disease, a naive model that always predicts healthy will achieve ninety-nine percent accuracy while completely failing to detect any actual illness.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Precision', 'Easy', 'What does precision measure in classification evaluation, and in what business scenarios is high precision particularly critical?', 'Precision is a vital evaluation metric that measures the proportion of positive predictions made by a classification model that were actually correct. It is calculated by dividing the number of true positive predictions by the total number of predicted positives, which includes both true positives and false positives. High precision is especially critical in application domains where false positive errors carry severe financial, legal, or operational consequences. A classic example is spam email filtering, where high precision ensures that important legitimate emails are rarely misclassified as spam and sent to the junk folder, thereby preventing user frustration and missed communication while maintaining overall system reliability.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Recall', 'Easy', 'What is recall in binary classification models, and why is it important in medical diagnosis applications?', 'Recall, also known as sensitivity or the true positive rate, is a critical evaluation metric that measures the ability of a classification model to identify all actual positive instances within a dataset. It is computed by dividing the number of true positive predictions by the total number of actual positive samples, combining true positives and false negatives. Recall is exceptionally important in medical diagnosis applications, such as detecting malignant tumors or contagious diseases, because failing to identify a sick patient carries catastrophic health consequences. Maximizing recall ensures that the vast majority of true positive cases are successfully captured, even if it results in a higher number of false alarms.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Feature Scaling', 'Easy', 'Why is feature scaling necessary when preparing data for machine learning algorithms like K-Nearest Neighbors or Support Vector Machines?', 'Feature scaling is an essential data preprocessing step used to normalize the range of independent input variables or features within a dataset. Many machine learning algorithms, including K-Nearest Neighbors and Support Vector Machines, rely heavily on distance calculations or gradient descent optimization to learn patterns from data. If input features have vastly different numeric scales, such as age measured in decades and income measured in tens of thousands, features with larger magnitudes will disproportionately dominate the distance metrics and objective functions. Scaling ensures that all features contribute equally to the model learning process, leading to faster convergence and more accurate predictions.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'F1 Score', 'Medium', 'What is the F1 score in machine learning evaluation, and why is it preferred over accuracy when working with imbalanced datasets?', 'The F1 score is a comprehensive evaluation metric that computes the harmonic mean of precision and recall, providing a single balanced score that accounts for both false positives and false negatives. Unlike simple accuracy, which can be heavily skewed when one class dominates the dataset, the F1 score penalizes models that fail to capture minority classes effectively. By combining precision and recall into one cohesive number, data scientists can accurately assess model performance on skewed distributions where balancing the trade-off between finding all positive instances and maintaining prediction purity is essential for reliable decision-making.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Confusion Matrix', 'Medium', 'What is a confusion matrix, and how does it help data scientists evaluate the performance of a classification model?', 'A confusion matrix is a tabular summary layout used to evaluate the performance of a classification model by comparing its predicted category labels against the actual ground truth labels. It breaks down prediction outcomes into four distinct categories: true positives, true negatives, false positives, and false negatives. This detailed breakdown allows data scientists to look beyond overall accuracy and identify specific types of errors the model is making. By examining the confusion matrix, practitioners can compute derived metrics like precision, recall, and specificity, enabling them to fine-tune decision thresholds and address specific failure modes in their predictive algorithms.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Imbalanced Data', 'Medium', 'What challenges does imbalanced data present in machine learning classification tasks, and what techniques can be used to address them?', 'Imbalanced data occurs when one class in a classification dataset significantly outnumbers the other classes, leading models to develop a strong bias toward the majority class and poor predictive performance on minority classes. This common scenario frequently appears in fraud detection and rare disease diagnosis. To address this issue, data scientists employ various resampling techniques, such as oversampling the minority class using synthetic data generation methods or undersampling the majority class. Additionally, practitioners can use specialized evaluation metrics like precision-recall curves and F1 scores, or apply cost-sensitive learning algorithms that heavily penalize misclassifications of the minority class during training.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Grid Search', 'Medium', 'What is Grid Search in machine learning, and how is it used during hyperparameter tuning?', 'Grid Search is an exhaustive hyperparameter optimization technique used to find the best combination of parameters for a machine learning model. Practitioners define a specific grid of hyperparameter values, and the grid search algorithm systematically trains and evaluates models using every possible combination within that defined space. Cross-validation is typically applied during this process to ensure performance estimates are robust and generalizable. While grid search guarantees finding the optimal hyperparameter set within the specified grid, it can become computationally expensive and slow when dealing with large parameter spaces and complex models, prompting alternative methods like random search for efficiency.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'ROC Curve', 'Hard', 'What is a Receiver Operating Characteristic curve, and what insights does it provide about binary classification model performance?', 'A Receiver Operating Characteristic curve is a graphical plot that illustrates the diagnostic ability of a binary classification system across all possible classification thresholds. The curve is created by plotting the true positive rate against the false positive rate at various threshold settings. It provides data scientists with a visual tool to understand the inherent trade-off between sensitivity and specificity as the decision threshold varies. A model with random guessing produces a diagonal line from corner to corner, whereas a superior model bends sharply toward the top left corner, indicating high true positive rates alongside low false positive rates across diverse threshold choices.');
INSERT INTO questions (role_id, topic, difficulty, question_text, ideal_answer) VALUES (3, 'Principal Component Analysis (PCA)', 'Hard', 'What is Principal Component Analysis, and how does dimensionality reduction help improve machine learning pipeline efficiency?', 'Principal Component Analysis is an unsupervised linear dimensionality reduction technique used to simplify complex datasets while retaining maximum variance and information. It transforms correlated original variables into a smaller set of uncorrelated orthogonal variables called principal components, ordered by the amount of variance they capture. Dimensionality reduction significantly improves machine learning pipeline efficiency by reducing computational training time, mitigating the curse of dimensionality, and removing multicollinearity among features. By projecting high-dimensional data onto a lower-dimensional subspace, practitioners can also visualize complex relationships more effectively and prevent overfitting in models with limited training samples.');
